// Small deterministic demonstrations, not trained models or performance predictions.
const finite=x=>Number.isFinite(x);
export function softmax(xs){if(!xs.length||!xs.every(finite))throw new RangeError('Finite logits required');const m=Math.max(...xs),e=xs.map(x=>Math.exp(x-m)),z=e.reduce((a,b)=>a+b,0);return e.map(x=>x/z);}
export function normalize(xs,kind='layer',epsilon=1e-5){if(!xs.length||!xs.every(finite)||!finite(epsilon)||epsilon<=0||!['layer','rms'].includes(kind))throw new RangeError('Normalization domain');const mean=xs.reduce((a,b)=>a+b,0)/xs.length,center=kind==='layer'?mean:0,second=xs.reduce((s,x)=>s+(x-center)**2,0)/xs.length;return {mean,second,scale:Math.sqrt(second+epsilon),values:xs.map(x=>(x-center)/Math.sqrt(second+epsilon))};}
export const activationNames=['ReLU','Leaky ReLU','Sigmoid','Tanh','GELU (tanh approximation)','SiLU / Swish','Hardtanh'];
export function activation(name,x){if(!activationNames.includes(name)||!finite(x))throw new RangeError('Activation domain');switch(name){case 'ReLU':return Math.max(0,x);case 'Leaky ReLU':return x>=0?x:.1*x;case 'Sigmoid':return x>=0?1/(1+Math.exp(-x)):Math.exp(x)/(1+Math.exp(x));case 'Tanh':return Math.tanh(x);case 'GELU (tanh approximation)':return .5*x*(1+Math.tanh(Math.sqrt(2/Math.PI)*(x+.044715*x**3)));case 'SiLU / Swish':return x*activation('Sigmoid',x);case 'Hardtanh':return Math.min(1,Math.max(-1,x));}}
export const depthSources=[[1,0],[0,1],[-1,0],[0,-1]];
export function depthMix(query){if(!Array.isArray(query)||query.length!==2||!query.every(finite))throw new RangeError('Two-dimensional query');const scores=depthSources.map(v=>normalize(v,'rms').values.reduce((s,x,i)=>s+x*query[i],0)),weights=softmax(scores),values=[0,1].map(j=>weights.reduce((s,w,i)=>s+w*depthSources[i][j],0));return {scores,weights,values};}
// Same scalar output embeddings, different orders of mixture and softmax.
export function outputMixture(pi){if(!finite(pi)||pi<0||pi>1)throw new RangeError('Mixture probability');const w=[-1,0,1],a=softmax(w.map(x=>-2*x)),b=softmax(w.map(x=>2*x)),context=softmax(w.map(x=>(-2*pi+2*(1-pi))*x)),probability=a.map((x,i)=>pi*x+(1-pi)*b[i]);return {a,b,context,probability};}
export function logOdds(rows){if(!rows.length||rows.some(r=>r.length!==rows[0].length||!r.every(x=>finite(x)&&x>0)))throw new RangeError('Positive rectangular probabilities');return rows.map(r=>r.slice(0,-1).map(p=>Math.log(p/r.at(-1))));}
export const reversibleFrames=[{title:'Keep the input',x1:2,x2:3,y1:null,y2:null,explanation:'f(x)=2x, g(x)=−x/2. The functions themselves need not be invertible in general.'},{title:'First write',x1:2,x2:3,y1:8,y2:null,explanation:'y₁=x₁+f(x₂)=2+6=8. Keep x₂ for the next write.'},{title:'Second write',x1:2,x2:3,y1:8,y2:-1,explanation:'y₂=x₂+g(y₁)=3−4=−1. Only y₁,y₂ are needed to reconstruct these inputs.'},{title:'Recover the second input',x1:null,x2:3,y1:8,y2:-1,explanation:'x₂=y₂−g(y₁)=−1−(−4)=3. Recompute g from the known output.'},{title:'Recover the first input',x1:2,x2:3,y1:8,y2:-1,explanation:'x₁=y₁−f(x₂)=8−6=2. Reconstruction order is essential.'}];
export function reversible(x1,x2){if(!finite(x1)||!finite(x2))throw new RangeError('Finite inputs');const y1=x1+2*x2,y2=x2-y1/2,recovered2=y2+y1/2,recovered1=y1-2*recovered2;return {y1,y2,recovered1,recovered2};}
export function budget({d,h,kv,m,layers,vocab,tokens=1,bytes=2,gated=true,tied=true}){const ints=[d,h,kv,m,layers,vocab,tokens,bytes];if(!ints.every(x=>Number.isSafeInteger(x)&&x>0)||d%h||h%kv)throw new RangeError('Integral conventional head geometry required');const head=d/h,attention=2*d*d*(1+kv/h),ffn=(gated?3:2)*d*m,embedding=(tied?1:2)*vocab*d,cache=2*layers*tokens*kv*head*bytes,total=layers*(attention+ffn)+embedding;return {head,attention,ffn,embedding,cache,total};}
